package com.jobportal;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;
import org.springframework.security.core.userdetails.*;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.annotation.PostConstruct;
@Configuration @EnableMethodSecurity class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean UserDetailsService noPasswordLogin(){return username->{throw new UsernameNotFoundException("Password authentication is not configured");};}
 @Bean CorsConfigurationSource cors(@Value("${app.cors-origins}") String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
 @Bean SecurityFilterChain chain(HttpSecurity http,JwtFilter jwt)throws Exception{return http.csrf(x->x.disable()).cors(x->{}).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/register","/api/auth/login","/api/jobs/**","/api/meta/**","/actuator/health","/actuator/info","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
@Component class Tokens {
 @Value("${app.jwt-secret}") String secret; @Value("${app.jwt-ttl}") long ttl; final ObjectMapper mapper=new ObjectMapper();
 @PostConstruct void validateSecret(){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 bytes");if(ttl<60)throw new IllegalStateException("JWT_TTL must be at least 60 seconds");}
 String issue(UserAccount u){try{long now=System.currentTimeMillis()/1000;Map<String,Object> p=Map.of("sub",u.email,"uid",u.id,"roles",u.roles.stream().map(r->r.name).toList(),"iat",now,"exp",now+ttl);String h=enc("{\"alg\":\"HS256\",\"typ\":\"JWT\"}");String body=enc(mapper.writeValueAsBytes(p));String data=h+"."+body;return data+"."+sign(data);}catch(Exception e){throw new IllegalStateException(e);}}
 Map<?,?> verify(String token){try{String[] x=token.split("\\.");if(x.length!=3||!java.security.MessageDigest.isEqual(sign(x[0]+"."+x[1]).getBytes(StandardCharsets.UTF_8),x[2].getBytes(StandardCharsets.UTF_8)))throw new RuntimeException();Map<?,?> p=mapper.readValue(Base64.getUrlDecoder().decode(x[1]),Map.class);if(((Number)p.get("exp")).longValue()<=System.currentTimeMillis()/1000)throw new RuntimeException();return p;}catch(Exception e){throw new BadCredentialsException("Invalid or expired token");}}
 String sign(String d)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(d.getBytes(StandardCharsets.UTF_8)));}String enc(String s){return enc(s.getBytes(StandardCharsets.UTF_8));}String enc(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
}
@Component class JwtFilter extends OncePerRequestFilter {
 final Tokens tokens;final UserRepository users;JwtFilter(Tokens t,UserRepository u){tokens=t;users=u;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Map<?,?> p=tokens.verify(h.substring(7));UserAccount u=users.findById(((Number)p.get("uid")).longValue()).orElseThrow();if(!u.enabled)throw new BadCredentialsException("Disabled account");List<GrantedAuthority> a=u.roles.stream().map(r->new SimpleGrantedAuthority("ROLE_"+r.name)).map(x->(GrantedAuthority)x).toList();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.email,null,a));}catch(Exception e){SecurityContextHolder.clearContext();res.setStatus(401);res.setContentType("application/problem+json");res.getWriter().write("{\"title\":\"Unauthorized\",\"status\":401}");return;}chain.doFilter(req,res);}
}
